type crmActors struct {
	Admin, East, EastPeer, North runtimeClient
	EastOrg, NorthOrg            string
	AdminID                      string
}

var crmSetup struct {
	sync.Mutex
	ready bool
	value crmActors
}

func require2xx(t *testing.T, response runtimeResponse, operation string) {
	t.Helper()
	if response.Status/100 != 2 {
		t.Fatalf("%s status=%d body=%s", operation, response.Status, strings.TrimSpace(string(response.Body)))
	}
}

func findString(body []byte, key string) string {
	var value any
	if json.Unmarshal(body, &value) != nil {
		return ""
	}
	var walk func(any) string
	walk = func(current any) string {
		switch typed := current.(type) {
		case map[string]any:
			if found, ok := typed[key].(string); ok && found != "" {
				return found
			}
			for _, nested := range typed {
				if found := walk(nested); found != "" {
					return found
				}
			}
		case []any:
			for _, nested := range typed {
				if found := walk(nested); found != "" {
					return found
				}
			}
		}
		return ""
	}
	return walk(value)
}

func tokenSubject(token string) string {
	parts := strings.Split(token, ".")
	if len(parts) < 2 {
		return ""
	}
	payload, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return ""
	}
	var claims map[string]any
	if json.Unmarshal(payload, &claims) != nil {
		return ""
	}
	for _, key := range []string{"sub", "user_id", "principal_id"} {
		if value, ok := claims[key].(string); ok && value != "" {
			return value
		}
	}
	return ""
}

func setupActors(t *testing.T) crmActors {
	t.Helper()
	crmSetup.Lock()
	defer crmSetup.Unlock()
	if crmSetup.ready {
		return crmSetup.value
	}
	admin := workspaceAdminClient(t)
	adminID := tokenSubject(admin.Token)
	provision := func(code, name string, sortOrder int) string {
		invoke := func() (runtimeResponse, error) {
			return admin.runObjectAction(t.Context(), "sales_person_profile", "sales_person_profile.provision_department", map[string]any{
				"code": code, "name": name, "sort_order": sortOrder,
			}, "crm-department-"+code)
		}
		response, err := invoke()
		if err != nil {
			t.Fatal(err)
		}
		if response.Status == http.StatusConflict && strings.Contains(string(response.Body), "auth.authorization_stale") {
			admin = workspaceAdminClient(t)
			response, err = invoke()
			if err != nil {
				t.Fatal(err)
			}
		}
		require2xx(t, response, "provision department")
		organizationID := findString(response.Body, "organization_id")
		if organizationID == "" {
			t.Fatalf("department response has no organization_id: %s", response.Body)
		}
		admin = workspaceAdminClient(t)
		return organizationID
	}
	eastOrg := provision("east", "华东区", 10)
	northOrg := provision("north", "华北区", 20)
	deliver := func(loginID, displayName, code, orgID string) runtimeClient {
		data := map[string]any{"login_id": loginID, "display_name": displayName, "acceptance_code": code, "role_key": "sales_rep"}
		if adminID != "" {
			data["manager"] = adminID
		}
		invoke := func() (runtimeResponse, error) {
			return admin.request(t.Context(), http.MethodPost, "/records/sales_person_profile/actions/sales_person_profile.deliver_identity", map[string]any{
				"data": data, "target_organization_id": orgID,
			}, runtimeRequestOptions{IdempotencyKey: "crm-identity-" + code})
		}
		response, err := invoke()
		if err != nil {
			t.Fatal(err)
		}
		if response.Status == http.StatusConflict && strings.Contains(string(response.Body), "auth.authorization_stale") {
			admin = workspaceAdminClient(t)
			response, err = invoke()
			if err != nil {
				t.Fatal(err)
			}
		}
		require2xx(t, response, "deliver identity")
		initial := findString(response.Body, "initial_password")
		changed := "M1-Crm-" + code + "-Changed!2026"
		client := loginCredential(t, loginID, initial, changed)
		admin = workspaceAdminClient(t)
		return client
	}
	actors := crmActors{
		Admin: admin, EastOrg: eastOrg, NorthOrg: northOrg, AdminID: adminID,
		East:     deliver("east.rep@crm.invalid", "华东销售", "east-rep", eastOrg),
		EastPeer: deliver("east.peer@crm.invalid", "华东销售同事", "east-peer", eastOrg),
		North:    deliver("north.rep@crm.invalid", "华北销售", "north-rep", northOrg),
	}
	crmSetup.value, crmSetup.ready = actors, true
	return actors
}

