func getRecord(t *testing.T, client runtimeClient, objectKey, recordID string) recordEnvelope {
	t.Helper()
	response, err := client.request(t.Context(), http.MethodGet, "/records/"+url.PathEscape(objectKey)+"/items/"+url.PathEscape(recordID), nil, runtimeRequestOptions{})
