func findRecordByCompany(t *testing.T, client runtimeClient, objectKey, company string) (recordEnvelope, bool) {
	t.Helper()
	page, err := client.listRecords(t.Context(), objectKey, 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	for _, item := range page.Items {
