func relationID(value any) string {
	if direct, ok := value.(string); ok {
		return direct
	}
	if object, ok := value.(map[string]any); ok {
		for _, key := range []string{"id", "record_id", "value"} {
			if result, ok := object[key].(string); ok {
				return result
			}
		}
	}
	return ""
}

func countCustomersForLead(t *testing.T, client runtimeClient, leadID string) int {
	t.Helper()
	page, err := client.listRecords(t.Context(), "customer", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	count := 0
	for _, item := range page.Items {
		if relationID(item.Data["source_lead"]) == leadID {
			count++
		}
	}
	return count
}

func runWorkflow(t *testing.T, client runtimeClient, workflowKey, leadID, logical string, input map[string]any) runtimeResponse {
	t.Helper()
	payload := map[string]any{"record_id": leadID}
	for key, value := range input {
		payload[key] = value
	}
	body := map[string]any{"payload": payload}
	response, err := client.request(t.Context(), http.MethodPost, "/workflow/definitions/"+url.PathEscape(workflowKey)+"/run", body, runtimeRequestOptions{IdempotencyKey: logical})
	if err != nil {
		t.Fatal(err)
	}
	return response
}

func waitForTask(t *testing.T, client runtimeClient, processID string) workflowTask {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		response, err := client.request(t.Context(), http.MethodGet, "/workflow/tasks?status=open&approval_mode=any&limit=100", nil, runtimeRequestOptions{})
		if err != nil {
			t.Fatal(err)
		}
		if response.Status/100 == 2 {
			tasks, err := decodeWorkflowTasks(response.Body)
			if err != nil {
				t.Fatal(err)
			}
			for _, task := range tasks {
				if processID == "" || task.ProcessID == processID {
					return task
				}
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("pending workflow task not found for process %q", processID)
	return workflowTask{}
}

func decodeJSONMap(t *testing.T, body []byte) map[string]any {
	t.Helper()
	var result map[string]any
	if err := json.Unmarshal(body, &result); err != nil {
		t.Fatalf("decode JSON: %v body=%s", err, body)
	}
	return result
}

