func TestBF01LeadLifecycleAndOwnership(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	logical := uniqueForPhase("BF01")
	leadID := createLead(t, actors.East, logical, "BF01华东线索", "88000.00")
	replayedID := createLead(t, actors.East, logical, "BF01华东线索", "88000.00")
	if replayedID != leadID {
		t.Fatalf("idempotent create changed identity: %q != %q", replayedID, leadID)
	}
	update := runLeadAction(t, actors.East, leadID, "update_owned", logical+"-update", map[string]any{"contact_name": "更新联系人", "source": "referral"})
	require2xx(t, update, "owner update")
	beforeDenied := getRecord(t, actors.East, "lead", leadID)
	denied := runLeadAction(t, actors.EastPeer, leadID, "update_owned", logical+"-peer-denied", map[string]any{"contact_name": "越权篡改"})
	if denied.Status != http.StatusForbidden && denied.Status != http.StatusNotFound {
