func TestBF05DepartmentScopePaginationAndRoleNavigation(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	eastID := createLead(t, actors.East, uniqueForPhase("BF05-east"), "BF05华东可见", "1000.00")
	eastPeerID := createLead(t, actors.EastPeer, uniqueForPhase("BF05-east-peer"), "BF05华东同事可见", "1500.00")
	northID := createLead(t, actors.North, uniqueForPhase("BF05-north"), "BF05华北可见", "2000.00")
	eastPage, err := actors.East.listRecords(t.Context(), "lead", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	northPage, err := actors.North.listRecords(t.Context(), "lead", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	adminPage, err := actors.Admin.listRecords(t.Context(), "lead", 1, 9999)
	if err != nil {
		t.Fatal(err)
	}
	contains := func(page recordPage, id string) bool {
		for _, item := range page.Items {
			if item.ID == id {
				return true
			}
		}
		return false
	}
	if !contains(eastPage, eastID) || !contains(eastPage, eastPeerID) || contains(eastPage, northID) || !contains(northPage, northID) || contains(northPage, eastID) || contains(northPage, eastPeerID) || !contains(adminPage, eastID) || !contains(adminPage, eastPeerID) || !contains(adminPage, northID) {
		t.Fatal("department/all visibility boundary failed")
	}
	cross, err := actors.East.request(t.Context(), http.MethodGet, "/records/lead/items/"+northID, nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	if cross.Status != http.StatusForbidden && cross.Status != http.StatusNotFound {
		t.Fatalf("cross-department detail leaked status=%d", cross.Status)
	}
	if adminPage.PageSize != 200 || len(adminPage.Items) > 200 {
		t.Fatalf("pagination is not bounded: page_size=%d items=%d", adminPage.PageSize, len(adminPage.Items))
	}
	repCatalog, err := actors.East.request(t.Context(), http.MethodGet, "/records/lead/actions", nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	directorCatalog, err := actors.Admin.request(t.Context(), http.MethodGet, "/records/lead/actions", nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, repCatalog, "rep action catalog")
	require2xx(t, directorCatalog, "director action catalog")
	if !strings.Contains(string(repCatalog.Body), "lead.register") || strings.Contains(string(directorCatalog.Body), "lead.register") {
		t.Fatal("role entry surface did not distinguish sales and director")
