func TestBF07FunnelAggregationAndSalesDenial(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	base := uniqueForPhase("BF07")
	newID := createLead(t, actors.North, base+"-new", "BF07新建", "10.10")
	contactedID := createLead(t, actors.North, base+"-contacted", "BF07跟进", "20.20")
	require2xx(t, runLeadAction(t, actors.North, contactedID, "advance", base+"-contacted-step", map[string]any{"target_status": "contacted"}), "BF07 contacted")
	qualifiedID := createLead(t, actors.North, base+"-qualified", "BF07合格", "30.30")
	qualifyLead(t, actors.North, qualifiedID, base+"-qualified")
	lostID := createLead(t, actors.North, base+"-lost", "BF07丢失", "40.40")
	qualifyLead(t, actors.North, lostID, base+"-lost")
	require2xx(t, runLeadAction(t, actors.North, lostID, "advance", base+"-lost-step", map[string]any{"target_status": "lost"}), "BF07 lost")
	convertedID := createLead(t, actors.North, base+"-converted", "BF07转化", "50.50")
	qualifyLead(t, actors.North, convertedID, base+"-converted")
	require2xx(t, runLeadAction(t, actors.North, convertedID, "convert_direct", base+"-convert-step", map[string]any{}), "BF07 converted")
	_ = newID
	allLeads, err := actors.Admin.listRecords(t.Context(), "lead", 1, 200)
	if err != nil {
		t.Fatal(err)
	}
	expectedCount := map[string]int{}
	expectedSum := map[string]*big.Rat{}
	for _, item := range allLeads.Items {
		status := item.Data["status"].(string)
		expectedCount[status]++
		amount, ok := new(big.Rat).SetString(item.Data["expected_amount"].(string))
		if !ok {
			t.Fatal("invalid stored amount")
		}
		if expectedSum[status] == nil {
			expectedSum[status] = new(big.Rat)
		}
		expectedSum[status].Add(expectedSum[status], amount)
	}
	response, err := actors.Admin.request(t.Context(), http.MethodPost, "/report/lead_funnel/query", map[string]any{"parameters": map[string]any{}, "page_size": 200}, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, response, "director funnel report")
	var report struct {
		Rows []struct {
			Dimensions map[string]string `json:"dimensions"`
			Measures   map[string]string `json:"measures"`
		} `json:"rows"`
	}
	if err := json.Unmarshal(response.Body, &report); err != nil {
		t.Fatal(err)
	}
	for _, row := range report.Rows {
		status := row.Dimensions["status"]
		if row.Measures["lead_count"] != new(big.Int).SetInt64(int64(expectedCount[status])).String() {
			t.Fatalf("count mismatch for %s", status)
		}
		actual, ok := new(big.Rat).SetString(row.Measures["total_amount"])
		if !ok || expectedSum[status] == nil || actual.Cmp(expectedSum[status]) != 0 {
			t.Fatalf("sum mismatch for %s actual=%s expected=%v", status, row.Measures["total_amount"], expectedSum[status])
		}
		delete(expectedCount, status)
	}
	if len(expectedCount) != 0 {
		t.Fatalf("report omitted statuses: %v", expectedCount)
	}
	denied, err := actors.East.request(t.Context(), http.MethodPost, "/report/lead_funnel/query", map[string]any{"parameters": map[string]any{}, "page_size": 200}, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	if denied.Status != http.StatusForbidden {
		t.Fatalf("sales report access status=%d", denied.Status)
	}
	emitEvidence(t, phase, "BF07", passedStep("funnel", "report.funnel.exact", "runtime.report", []string{"15"}, map[string]any{
		"status_count": len(report.Rows), "counts_exact": true, "amount_sums_exact": true, "sales_access_denied": true,
	}))
}

