// Advance implements the project-owned lead.advance Handler.
func Advance(ctx context.Context, caps capabilities.AdvanceCapabilities, input capabilities.AdvanceInput) (capabilities.AdvanceOutput, error) {
	principal := caps.Execution.Principal()
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.AdvanceOutput{}, err
	}
	target := schema.LeadStatus(input.TargetStatus)
	if !legalLeadTransition(lead.Status, target) {
		return capabilities.AdvanceOutput{}, &capabilities.BusinessError{Code: "lead.advance.illegal_transition", Message: "the requested lead transition is not allowed"}
	}
	updated, err := caps.Lead.ConditionalUpdate(ctx, data.NewLeadUpdate(lead.ID).
		SetStatus(target).RequireStatusEqual(lead.Status, "lead.advance.status_conflict").WithExpectedUpdatedAt(lead.UpdatedAt))
	if err != nil {
		return capabilities.AdvanceOutput{}, err
	}
	if _, err := caps.LeadAudit.Create(ctx, schema.CreateLeadAudit{
		Lead: schema.NewLeadAuditLeadReference(updated.ID), Actor: principal.UserID,
		Operation: schema.LeadAuditOperation(target), FromStatus: schema.LeadAuditFromStatus(lead.Status),
		ToStatus: schema.LeadAuditToStatus(updated.Status), OccurredAt: time.Now().UTC(),
	}); err != nil {
		return capabilities.AdvanceOutput{}, err
	}
	return capabilities.AdvanceOutput{}, nil
}

func legalLeadTransition(from, to schema.LeadStatus) bool {
	return (from == schema.LeadStatusNew && to == schema.LeadStatusContacted) ||
		(from == schema.LeadStatusContacted && to == schema.LeadStatusQualified) ||
		(from == schema.LeadStatusQualified && to == schema.LeadStatusLost)
}
