// domainry:action-test-scaffold-v1
package crm

import (
	capabilities "example.com/domainry-m1-crm/backend/generated/capabilities"
	"testing"
	"time"
)

func TestScanStaleContactedSkipsWeekend(t *testing.T) {
	weekend := time.Date(2026, time.September, 6, 1, 0, 0, 0, time.UTC)
	_, err := ScanStaleContacted(t.Context(), capabilities.ScanStaleContactedCapabilities{}, capabilities.ScanStaleContactedInput{EvaluationTime: &weekend})
	if err != nil {
		t.Fatalf("weekend scan should be a no-op: %v", err)
	}
}
