package businessflow

import (
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"testing"
	"time"
)

func TestBF06WeekdayReminderDedupAndRestart(t *testing.T) {
	phase := managedPhase(t)
	actors := setupActors(t)
	logical := uniqueForPhase("BF06")
	leadID := createLead(t, actors.East, logical, "BF06工作日逾期提醒", "66000.00")
	lead := getRecord(t, actors.East, "lead", leadID)
	if phase == "initial" {
		contacted := runLeadAction(t, actors.East, leadID, "advance", logical+"-contacted", map[string]any{"target_status": "contacted"})
		require2xx(t, contacted, "BF06 contacted setup")
		lead = getRecord(t, actors.East, "lead", leadID)
	}
	if statusValue(lead) != "contacted" {
		t.Fatalf("BF06 durable setup status=%s", statusValue(lead))
	}

	// The internal bulk Action remains unavailable to every human Role.
	directDenied, err := actors.Admin.runObjectAction(t.Context(), "lead", "lead.scan_stale_contacted", map[string]any{
		"evaluation_time": "2026-09-21T01:00:00Z",
	}, logical+"-direct-denied")
	if err != nil {
		t.Fatal(err)
	}
	if directDenied.Status != http.StatusForbidden && directDenied.Status != http.StatusNotFound {
		t.Fatalf("human direct scheduled Action status=%d body=%s", directDenied.Status, directDenied.Body)
	}

	// Exercise the published Scheduler-owned definition-run route with the exact
	// stable key and governed-operation reason. The production definition carries
	// no caller payload and therefore uses the host clock.
	runScheduler := func(client runtimeClient, key string) runtimeResponse {
		response, err := client.request(t.Context(), http.MethodPost,
			"/scheduler/definitions/"+url.PathEscape("weekday_stale_lead_followup")+"/run", nil,
			runtimeRequestOptions{IdempotencyKey: key, OperationReason: "BF06 工作日逾期跟进提醒受控执行"})
		if err != nil {
			t.Fatal(err)
		}
		return response
	}
	repDenied := runScheduler(actors.East, logical+"-scheduler-rep-denied")
	if repDenied.Status != http.StatusForbidden {
		t.Fatalf("sales Scheduler execution status=%d body=%s", repDenied.Status, repDenied.Body)
	}
	scheduled := runScheduler(actors.Admin, logical+"-scheduler")
	require2xx(t, scheduled, "Scheduler definition run")
	schedulerRunID := findString(scheduled.Body, "id")
	if schedulerRunID == "" {
		t.Fatalf("Scheduler response has no run id: %s", scheduled.Body)
	}
	replayed := runScheduler(actors.Admin, logical+"-scheduler")
	require2xx(t, replayed, "Scheduler definition replay")
	if replayID := findString(replayed.Body, "id"); replayID != schedulerRunID {
		t.Fatalf("Scheduler idempotency changed run id: %q != %q", replayID, schedulerRunID)
	}

	// The published elapsed-time bridge is isolated from the production scheduled
	// Workflow. It proves a genuinely stale (>7 days) Monday evaluation through
	// service run_as without granting the internal Action to the director.
	evaluationTime := time.Date(2026, time.September, 21, 1, 0, 0, 0, time.UTC)
	updatedAt, err := time.Parse(time.RFC3339Nano, lead.UpdatedAt)
	if err != nil {
		t.Fatalf("parse lead updated_at %q: %v", lead.UpdatedAt, err)
	}
	if evaluationTime.Sub(updatedAt) <= 7*24*time.Hour {
		t.Fatalf("BF06 fixture is not genuinely stale: updated_at=%s evaluation_time=%s", updatedAt, evaluationTime)
	}
	assessment := runWorkflow(t, actors.Admin, "followup_elapsed_time_assessment", leadID, logical+"-assessment", map[string]any{
		"evaluation_time": evaluationTime.Format(time.RFC3339),
	})
	require2xx(t, assessment, "elapsed-time assessment workflow")

	countReminders := func() (int, recordEnvelope) {
		page, err := actors.Admin.listRecords(t.Context(), "followup_reminder", 1, 200)
		if err != nil {
			t.Fatal(err)
		}
		count := 0
		var found recordEnvelope
		for _, item := range page.Items {
			if relationID(item.Data["lead"]) == leadID {
				count++
				found = item
			}
		}
		return count, found
	}
	deadline := time.Now().Add(15 * time.Second)
	reminderCount, reminder := countReminders()
	for reminderCount != 1 && time.Now().Before(deadline) {
		time.Sleep(100 * time.Millisecond)
		reminderCount, reminder = countReminders()
	}
	if reminderCount != 1 || fmt.Sprint(reminder.Data["reminder_date"]) != "2026-09-21" {
		t.Fatalf("expected one Monday reminder, count=%d data=%v", reminderCount, reminder.Data)
	}

	secondAssessment := runWorkflow(t, actors.Admin, "followup_elapsed_time_assessment", leadID, logical+"-assessment-dedup", map[string]any{
		"evaluation_time": evaluationTime.Format(time.RFC3339),
	})
	require2xx(t, secondAssessment, "same-day assessment replay")
	time.Sleep(100 * time.Millisecond)
	afterDedup, _ := countReminders()
	if afterDedup != 1 {
		t.Fatalf("same-day reminder dedup failed: count=%d", afterDedup)
	}

	inbox, err := actors.East.request(t.Context(), http.MethodGet, "/notification/inbox?limit=100", nil, runtimeRequestOptions{})
	if err != nil {
		t.Fatal(err)
	}
	require2xx(t, inbox, "followup notification inbox")
	if !strings.Contains(string(inbox.Body), "lead.followup_overdue") || !strings.Contains(string(inbox.Body), leadID) {
		t.Fatalf("followup notification evidence missing: %s", inbox.Body)
	}

	emitEvidence(t, phase, "BF06", passedStep("scheduler", "scheduler.definition.run", "runtime.scheduler", []string{"14"}, map[string]any{
		"definition_id": "weekday_stale_lead_followup", "run_id": schedulerRunID,
		"scheduler_owned": true, "stable_idempotency_replay": true, "operation_reason_supplied": true,
		"sales_access_denied": true, "human_action_access_denied": true,
		"weekday": "Monday", "genuinely_stale": true, "reminder_count": reminderCount,
		"same_day_deduplicated": true, "notification_readable": true, "restart_persisted": phase == "restart",
	}))
}
